<?php

declare(strict_types=1);

namespace Fleet\Application\Command\Agent;

use Fleet\Application\Protocol\SignedRequest;
use Shared\Application\Audit\AuditableCommand;
use Shared\Application\Audit\AuditAction;
use Shared\Application\Audit\AuditContext;
use Shared\Application\Audit\Target;

/**
 * POST /agent/v1/enrollments (protocol §5): the request is signed with the new key (proof of possession) and carries
 * the enrollment token. The agent id is generated by the caller; an idempotent retry keeps the first agent.
 */
final readonly class EnrollAgent implements AuditableCommand
{
    public function __construct(public string $agentId, public SignedRequest $request)
    {
    }

    public function auditAction(): AuditAction
    {
        return AuditAction::named('fleet.enroll_agent');
    }

    public function auditTarget(): Target
    {
        return Target::of('agent', $this->agentId);
    }

    public function auditContext(): AuditContext
    {
        return AuditContext::empty();
    }
}
